"xMidYMid slice\"><rect width=\"180\" height=\"74\" fill=\"#e9eff4\"/><rect x=\"52\" y=\"7\" width=\"75\" height=\"61\" rx=\"3\" fill=\"#fff\" stroke=\"#d8e0e9\"/><rect x=\"61\" y=\"15\" width=\"57\" height=\"4\" rx=\"2\" fill=\"#db7545\"/><path d=\"M80 29h17l-2 6v4l9 15c2 4-1 7-5 7H77c-4 0-7-3-5-7l9-15v-4Z\" fill=\"#f1d470\" stroke=\"#9d8d4b\" stroke-width=\"1.3\"/><path d=\"M78 49h20l4 6H75Z\" fill=\"#e98a36\"/><path d=\"M84 26h9\" stroke=\"#7e8d9e\" stroke-width=\"3\" stroke-linecap=\"round\"/><rect x=\"61\" y=\"57\" width=\"57\" height=\"3\" rx=\"1.5\" fill=\"#e1e7ee\"/></svg><span class=\"thumb-badge\"><svg class=\"icon\"><use href=\"#i-pdf\"/></svg></span></div><div class=\"material-name\">Chemical Handling</div><div class=\"material-meta\">PDF · 5 MB</div></article>\n              <article class=\"material-card\" data-kind=\"Videos\" data-title=\"Confined Space\"><div class=\"material-thumb\"><svg viewBox=\"0 0 180 74\" preserveAspectRatio=\"xMidYMid slice\"><rect width=\"180\" height=\"74\" fill=\"#253948\"/><path d=\"M0 60 42 46l28 28H0Zm112 14 22-45 22 45\" fill=\"#465a64\"/><circle cx=\"87\" cy=\"30\" r=\"13\" fill=\"#dba06d\"/><path d=\"M73 25c2-11 8-16 15-16 10 0 15 6 16 16l-5 3H74Z\" fill=\"#f3a526\"/><path d=\"M70 25h37\" stroke=\"#ffcf61\" stroke-width=\"4\"/><path d=\"M66 75c2-23 10-35 21-38 13 3 20 15 22 38\" fill=\"#e2aa72\"/><path d=\"M34 10h18v48H34z\" fill=\"#788d9a\" opacity=\".55\"/><path d=\"M42 13v42m0-30 15-10\" stroke=\"#d1ac45\" stroke-width=\"3\"/></svg><span class=\"play-badge\"><svg class=\"icon\"><use href=\"#i-play\"/></svg></span></div><div class=\"material-name\">Confined Space</div><div class=\"material-meta\">Video · 35 MB</div></article>\n              <article class=\"material-card\" data-kind=\"SOP\" data-title=\"First Aid SOP\"><div class=\"material-thumb\"><svg viewBox=\"0 0 180 74\" preserveAspectRatio=\"xMidYMid slice\"><rect width=\"180\" height=\"74\" fill=\"#e8edf3\"/><rect x=\"52\" y=\"7\" width=\"75\" height=\"61\" rx=\"3\" fill=\"#fff\" stroke=\"#d9e1eb\"/><rect x=\"62\" y=\"16\" width=\"55\" height=\"5\" rx=\"2\" fill=\"#a5bdd5\"/><rect x=\"62\" y=\"27\" width=\"54\" height=\"3\" rx=\"1.5\" fill=\"#e0e6ed\"/><rect x=\"62\" y=\"34\" width=\"54\" height=\"3\" rx=\"1.5\" fill=\"#e0e6ed\"/><rect x=\"62\" y=\"41\" width=\"54\" height=\"3\" rx=\"1.5\" fill=\"#e0e6ed\"/><rect x=\"62\" y=\"50\" width=\"22\" height=\"11\" rx=\"2\" fill=\"#d94b55\"/><path d=\"M73 52v7m-3.5-3.5h7\" stroke=\"#fff\" stroke-width=\"2\"/></svg><span class=\"thumb-badge\"><svg class=\"icon\"><use href=\"#i-pdf\"/></svg></span></div><div class=\"material-name\">First Aid SOP</div><div class=\"material-meta\">PDF · 2 MB</div></article>\n            </div>\n          </article>\n        </section>\n\n\n\n\n        <section class=\"panel incident-tracker-panel\" id=\"incident-tracker\">\n          <div class=\"incident-tracker-heading\">\n            <div><div class=\"step-title\"><span class=\"step-number\">6</span><h2>Incident Communication &amp; Learning Tracker</h2></div><p class=\"incident-tracker-note\">Auto-fed from single or bulk entries marked as Incident Communication. Selected employees / Present bulk rows count as reached; remaining = target people minus people reached.</p></div>\n            <button type=\"button\" class=\"btn btn-primary btn-small\" id=\"logIncidentButton\"><svg class=\"icon\"><use href=\"#i-plus\"/></svg>Log Incident Communication</button>\n          </div>\n          <div class=\"incident-summary\">\n            <div class=\"incident-summary-card\"><span class=\"incident-summary-icon\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></span><div class=\"incident-summary-copy\"><span>Incident Communications</span><strong id=\"incidentCount\">4</strong></div></div>\n            <div class=\"incident-summary-card\"><span class=\"incident-summary-icon\"><svg class=\"icon\"><use href=\"#i-users\"/></svg></span><div class=\"incident-summary-copy\"><span>People Reached</span><strong id=\"incidentPeopleReached\">282</strong></div></div>\n            <div class=\"incident-summary-card\"><span class=\"incident-summary-icon\"><svg class=\"icon\"><use href=\"#i-clock\"/></svg></span><div class=\"incident-summary-copy\"><span>People Remaining</span><strong id=\"incidentPeopleRemaining\">38</strong></div></div>\n          </div>\n          <div class=\"incident-toolbar\"><label class=\"incident-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"incidentSearch\" placeholder=\"Search incident, type or learning topic...\"/></label><select id=\"incidentTypeFilter\" aria-label=\"Filter by incident type\"><option value=\"\">All Incident Types</option><option>LTI</option><option>Fatality</option><option>Near Miss</option><option>First Aid</option><option>Property Damage</option><option>Other</option></select><select id=\"incidentStatusFilter\" aria-label=\"Filter by communication status\"><option value=\"\">All Status</option><option value=\"In Progress\">In Progress</option><option value=\"Complete\">Complete</option></select><span class=\"incident-source\">Training Entry → Incident Tracker</span></div>\n          <div class=\"table-wrap\"><table class=\"incident-table\"><thead><tr><th>Incident Ref</th><th>Type</th><th>Learning Topic / Remarks</th><th>Last Shared</th><th>Reached / Target</th><th>Remaining</th><th>Completion</th><th>Status</th></tr></thead><tbody id=\"incidentTableBody\"></tbody></table><div id=\"incidentEmpty\" class=\"incident-empty hidden\">No incident communications match the selected filters.</div></div>\n        </section>\n      </main>\n      <main class=\"page hidden\" id=\"employeeProfilePage\">\n        <section class=\"page-heading\">\n          <div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-users\"/></svg></div><div><h1>Employee Profile</h1><p class=\"page-subtitle\">Master employee details, contact information and searchable employee-linked records</p></div></div>\n          <div class=\"heading-actions\"><span class=\"case-demo-badge\">Master Directory · Demo</span><button type=\"button\" class=\"btn btn-primary\" id=\"epAddNew\"><svg class=\"icon\"><use href=\"#i-plus\"/></svg>New Employee</button></div>\n        </section>\n        <div class=\"ep-source-note\"><svg class=\"icon\"><use href=\"#i-shield-alert\"/></svg><div><strong>Employee Master Profile</strong><small>Create and maintain employee identity, photo, contact and personal details. Demo data stays in this tab only—do not enter real sensitive information.</small></div><span class=\"case-demo-badge\">Session only</span></div>\n        <section class=\"ep-summary-grid\" aria-label=\"Employee profile summary\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-users\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Employees</div><div class=\"stat-value\" id=\"epTotalEmployees\">0</div><div class=\"stat-period\">In the master directory</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Photos on File</div><div class=\"stat-value\" id=\"epPhotoCount\">0</div><div class=\"stat-period\">Local demo image previews</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-purple\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Linked Records</div><div class=\"stat-value\" id=\"epIndexedLogs\">0</div><div class=\"stat-period\">For the selected employee</div></div></article>\n        </section>\n        <div class=\"ep-workspace-grid\">\n          <section class=\"panel ep-panel ep-master-panel\" id=\"epMasterPanel\">\n            <div class=\"ep-panel-heading\"><div><span class=\"eyebrow\">MASTER EMPLOYEE</span><h2 id=\"epFormTitle\">Create Employee Profile</h2><p>Add the employee number and core identity details first.</p></div><button type=\"button\" class=\"btn btn-light btn-small hidden\" id=\"epCancelEdit\">Cancel edit</button></div>\n            <form id=\"employeeProfileForm\" novalidate>\n              <div class=\"ep-photo-block\"><div class=\"ep-photo-preview\" id=\"epPhotoPreview\"><span>EP</span></div><div class=\"ep-photo-copy\"><strong>Employee photo</strong><small>Profile image · JPG, PNG or WEBP · max 2 MB</small><div class=\"ep-photo-actions\"><label class=\"btn btn-light btn-small\" for=\"epPhotoInput\">Choose photo</label><button type=\"button\" class=\"btn btn-light btn-small\" id=\"epRemovePhoto\">Remove</button></div></div></div>\n              <input class=\"hidden\" type=\"file\" id=\"epPhotoInput\" accept=\"image/png,image/jpeg,image/webp\"/>\n              <div class=\"ep-form-grid\">\n                <div class=\"ep-field\"><label for=\"epEmployeeNo\">Employee No <span class=\"required\">*</span></label><input id=\"epEmployeeNo\" maxlength=\"32\" required placeholder=\"e.g. 1024\" autocomplete=\"off\"/></div>\n                <div class=\"ep-field\"><label for=\"epEmployeeName\">Full name <span class=\"required\">*</span></label><input id=\"epEmployeeName\" maxlength=\"90\" required placeholder=\"Employee name\" autocomplete=\"name\"/></div>\n                <div class=\"ep-field\"><label for=\"epMobile\">Mobile number <span class=\"required\">*</span></label><input id=\"epMobile\" type=\"tel\" maxlength=\"20\" required placeholder=\"e.g. +91 98765 43210\" autocomplete=\"tel\"/></div>\n                <div class=\"ep-field\"><label for=\"epDesignation\">Designation</label><input id=\"epDesignation\" maxlength=\"80\" placeholder=\"Job title\"/></div>\n                <div class=\"ep-field\"><label for=\"epDepartment\">Department</label><input id=\"epDepartment\" maxlength=\"80\" placeholder=\"Department / team\"/></div>\n                <div class=\"ep-field\"><label for=\"epGender\">Gender</label><select id=\"epGender\"><option value=\"\">Not specified</option><option>Female</option><option>Male</option><option>Other</option><option>Prefer not to say</option></select></div>\n                <div class=\"ep-field\"><label for=\"epDob\">Date of birth</label><input id=\"epDob\" type=\"date\"/></div>\n                <div class=\"ep-field\"><label for=\"epBloodGroup\">Blood group</label><select id=\"epBloodGroup\"><option value=\"\">Not specified</option><option>A+</option><option>A−</option><option>B+</option><option>B−</option><option>AB+</option><option>AB−</option><option>O+</option><option>O−</option></select></div>\n                <div class=\"ep-field\"><label for=\"epEmail\">Email</label><input id=\"epEmail\" type=\"email\" maxlength=\"120\" placeholder=\"name@example.com\" autocomplete=\"email\"/></div>\n                <div class=\"ep-field\"><label for=\"epEmergencyName\">Emergency contact</label><input id=\"epEmergencyName\" maxlength=\"90\" placeholder=\"Contact person\"/></div>\n                <div class=\"ep-field\"><label for=\"epEmergencyMobile\">Emergency mobile</label><input id=\"epEmergencyMobile\" type=\"tel\" maxlength=\"20\" placeholder=\"Contact number\"/></div>\n                <div class=\"ep-field\"><label for=\"epLocation\">Site / location</label><input id=\"epLocation\" maxlength=\"80\" placeholder=\"Site or work location\"/></div>\n                <div class=\"ep-field full\"><label for=\"epAddress\">Address / personal details</label><textarea id=\"epAddress\" maxlength=\"500\" rows=\"2\" placeholder=\"Address or other relevant personal details\"></textarea></div>\n                <div class=\"ep-field full\"><label for=\"epNotes\">Additional notes</label><textarea id=\"epNotes\" maxlength=\"500\" rows=\"2\" placeholder=\"Optional profile notes\"></textarea></div>\n              </div>\n              <div class=\"ep-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"epResetForm\">Reset form</button><button type=\"submit\" class=\"btn btn-primary\" id=\"epSubmit\">Save Employee</button></div>\n            </form>\n          </section>\n          <section class=\"panel ep-panel ep-directory-panel\">\n            <div class=\"ep-panel-heading\"><div><span class=\"eyebrow\">EMPLOYEE DIRECTORY</span><h2>Master Records</h2><p>Search by employee number, name, mobile, role or department.</p></div><span class=\"case-report-count\" id=\"epDirectoryCount\">0 employees</span></div>\n            <div class=\"ep-directory-toolbar\"><label class=\"ep-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"epDirectorySearch\" type=\"search\" placeholder=\"Search employee no, name, mobile...\" autocomplete=\"off\"/></label><select id=\"epDepartmentFilter\" aria-label=\"Filter employees by department\"><option value=\"\">All departments</option></select><span class=\"case-result-count\" id=\"epDirectoryMatches\">0 shown</span></div>\n            <div class=\"table-wrap\"><table class=\"ep-table\"><thead><tr><th>Employee No</th><th>Employee</th><th>Department / Role</th><th>Mobile</th><th>Actions</th></tr></thead><tbody id=\"epDirectoryBody\"></tbody></table><div class=\"ep-empty hidden\" id=\"epDirectoryEmpty\">No employee profiles match this search.</div></div>\n          </section>\n        </div>\n        <section class=\"panel ep-panel ep-detail-panel\" id=\"epDetailPanel\">\n          <div class=\"ep-detail-empty\" id=\"epDetailEmpty\"><div class=\"ep-empty-icon\"><svg class=\"icon\"><use href=\"#i-search\"/></svg></div><strong>Select an employee profile</strong><span>Choose View in the directory to see personal details and all linked logs by employee number.</span></div>\n          <div id=\"epDetailContent\" class=\"hidden\">\n            <div class=\"ep-profile-banner\" id=\"epProfileHeader\"></div>\n            <div class=\"ep-profile-stats\" id=\"epProfileStats\"></div>\n            <section class=\"ep-personal-section\"><div class=\"ep-subhead\"><div><span class=\"eyebrow\">MASTER DETAILS</span><h2>Personal &amp; Contact Details</h2></div><button type=\"button\" class=\"btn btn-light btn-small\" id=\"epEditSelected\"><svg class=\"icon\"><use href=\"#i-edit\"/></svg>Edit Profile</button></div><div class=\"ep-personal-grid\" id=\"epPersonalDetails\"></div></section>\n            <section class=\"ep-log-section\"><div class=\"ep-subhead\"><div><span class=\"eyebrow\">EMPLOYEE ACTIVITY</span><h2>Linked Logs &amp; Records</h2><p>Records are matched using this employee number or the employee name stored on a demo record.</p></div><span class=\"case-report-count\" id=\"epLogCount\">0 records</span></div>\n              <div class=\"ep-log-toolbar\"><label class=\"ep-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"epLogSearch\" type=\"search\" placeholder=\"Search this employee's logs, reference, topic...\" autocomplete=\"off\"/></label><select id=\"epLogTypeFilter\" aria-label=\"Filter employee log type\"><option value=\"\">All record types</option><option>Training</option><option>Case Report</option><option>Incident Communication</option><option>Certificate</option><option>Audit</option><option>Inspection</option><option>Daily Management</option></select><span class=\"case-result-count\" id=\"epLogMatches\">0 shown</span></div>\n              <div class=\"table-wrap\"><table class=\"ep-log-table\"><thead><tr><th>Date</th><th>Record Type</th><th>Reference</th><th>Details</th><th>Status</th></tr></thead><tbody id=\"epLogsBody\"></tbody></table><div class=\"ep-empty hidden\" id=\"epLogsEmpty\">No linked records match the current search.</div></div>\n            </section>\n          </div>\n        </section>\n      </main>\n      <main class=\"page hidden\" id=\"caseManagementPage\">\n        <section class=\"page-heading\">\n          <div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-briefcase\"/></svg></div><div><h1>Case Management</h1><p class=\"page-subtitle\">Review, manage and export reports submitted from your employee-facing portal</p></div></div><div class=\"heading-actions\"><button type=\"button\" class=\"btn btn-primary\" id=\"caseNewReport\"><svg class=\"icon\"><use href=\"#i-plus\"/></svg>Direct Data Entry</button></div>\n        </section>\n        <div class=\"case-source-note\"><svg class=\"icon\"><use href=\"#i-message\"/></svg><div class=\"case-source-copy\"><strong>Employee Front Page Reports</strong><small>Central inbox for seven report types. Live portal sync is not connected in this demo yet.</small></div><span class=\"case-demo-badge\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg>Sample demo records</span></div>\n        <section class=\"case-summary-grid\" aria-label=\"Case report summary\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Reports</div><div class=\"stat-value\" id=\"caseTotalReports\">10</div><div class=\"stat-period\" id=\"caseTotalCaption\">All categories</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-red\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Open</div><div class=\"stat-value\" id=\"caseOpenReports\">0</div><div class=\"stat-period\">Awaiting action</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clock\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">In Review / Progress</div><div class=\"stat-value\" id=\"caseInProgressReports\">0</div><div class=\"stat-period\">Being reviewed</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Resolved / Closed</div><div class=\"stat-value\" id=\"caseResolvedReports\">0</div><div class=\"stat-period\">Completed reports</div></div></article>\n        </section>\n        <section class=\"case-charts\" id=\"caseCharts\" aria-label=\"Case report graphs\"></section>\n        <section class=\"panel case-panel\">\n          <div class=\"case-panel-topline\"><div class=\"case-panel-title\"><span class=\"eyebrow\">EMPLOYEE SUBMISSIONS</span><h2 id=\"caseReportHeading\">All Reports</h2><p id=\"caseReportSubheading\">All reports from the employee-facing reporting portal.</p></div><span class=\"case-report-count\" id=\"caseReportCount\">10 reports</span></div>\n          <div class=\"case-category-tabs\" id=\"caseCategoryTabs\" aria-label=\"Filter case reports by category\">\n            <div class=\"case-all-report-actions\"><button type=\"button\" class=\"case-category-tab active\" data-case-category=\"All Reports\" aria-pressed=\"true\">All Reports</button><button type=\"button\" class=\"btn btn-light btn-small case-inline-export\" id=\"caseExportCsvButton\"><svg class=\"icon\"><use href=\"#i-download\"/></svg>Export CSV</button><button type=\"button\" class=\"btn btn-primary btn-small case-inline-export\" id=\"caseExportReportButton\"><svg class=\"icon\"><use href=\"#i-file\"/></svg>Export Designed Report</button></div>\n            <button type=\"button\" class=\"case-category-tab\" data-case-category=\"Near Miss\" aria-pressed=\"false\">Near Miss</button>\n            <button type=\"button\" class=\"case-category-tab\" data-case-category=\"Safety Observations\" aria-pressed=\"false\">Safety Observations</button>\n            <button type=\"button\" class=\"case-category-tab\" data-case-category=\"Hazard\" aria-pressed=\"false\">Hazard</button>\n            <button type=\"button\" class=\"case-category-tab\" data-case-category=\"Feedback\" aria-pressed=\"false\">Feedback</button>\n            <button type=\"button\" class=\"case-category-tab\" data-case-category=\"Suggestions\" aria-pressed=\"false\">Suggestions</button>\n            <button type=\"button\" class=\"case-category-tab\" data-case-category=\"Speak Up\" aria-pressed=\"false\">Speak Up</button>\n            <button type=\"button\" class=\"case-category-tab\" data-case-category=\"Grievances\" aria-pressed=\"false\">Grievances</button>\n          </div>\n          <div class=\"case-toolbar\">\n            <label class=\"case-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"caseSearch\" type=\"search\" placeholder=\"Search report ID, detail, person or location...\" autocomplete=\"off\"/></label>\n            <select id=\"caseStatusFilter\" aria-label=\"Filter by status\"><option value=\"\">All Statuses</option><option>Open</option><option>In Review</option><option>In Progress</option><option>Resolved</option><option>Closed</option></select>\n            <select id=\"casePriorityFilter\" aria-label=\"Filter by priority\"><option value=\"\">All Priorities</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select>\n            <button type=\"button\" class=\"btn btn-light btn-small\" id=\"caseResetFilters\">Reset filters</button>\n            <span class=\"case-result-count\" id=\"caseFilteredCount\">10 submissions</span>\n          </div>\n          <div class=\"table-wrap\"><table class=\"case-report-table\"><thead><tr><th>Report ID</th><th>Category</th><th>Report / Location</th><th>Reported By</th><th>Submitted</th><th>Priority</th><th>Status · Change</th><th>Actions</th></tr></thead><tbody id=\"caseReportBody\"></tbody></table><div class=\"case-empty hidden\" id=\"caseEmptyState\">No reports match the selected category and filters.</div></div>\n          <p class=\"case-confidential-note\"><strong>Demo behavior:</strong> Sample records, edits, status changes and deletes are temporary in this prototype; live portal sync needs the backend connection. <strong>Confidential handling:</strong> Speak Up and Grievance submissions are shown as Anonymous / Confidential.</p>\n        </section>\n      </main>\n      <main class=\"page hidden\" id=\"communicationsPage\">\n        <section class=\"page-heading\">\n          <div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-message\"/></svg></div><div><h1>Communications</h1><p class=\"page-subtitle\">Create, release and broadcast safety messages to the employee front page</p></div></div>\n        </section>\n        <div class=\"comms-source-note\"><svg class=\"icon\"><use href=\"#i-message\"/></svg><div><strong>Employee Front Page Broadcast Center</strong><small>Matches the employee front page and bottom navigation: Safety Alerts, Circulars &amp; Notices, and Upcoming Events. Live delivery will be connected later.</small></div><span class=\"case-demo-badge\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg>Demo mode</span></div>\n        <section class=\"comms-summary-grid\" aria-label=\"Communications summary\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-message\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Communications</div><div class=\"stat-value\" id=\"commTotalCount\">5</div><div class=\"stat-period\">All categories</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Released / Published</div><div class=\"stat-value\" id=\"commPublishedCount\">4</div><div class=\"stat-period\">Visible to employees</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clock\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Drafts</div><div class=\"stat-value\" id=\"commDraftCount\">1</div><div class=\"stat-period\">Not on front page</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-purple\"><svg class=\"icon\"><use href=\"#i-calendar\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Upcoming Events</div><div class=\"stat-value\" id=\"commEventCount\">1</div><div class=\"stat-period\">Event notices</div></div></article>\n        </section>\n        <section class=\"panel comms-published-summary\" aria-live=\"polite\">\n          <div class=\"comms-published-summary-head\"><div><span class=\"eyebrow\">EMPLOYEE-FACING CONTENT</span><h2>Published So Far</h2><p>Overview of released and broadcast items currently visible to employees.</p></div><span class=\"case-report-count\" id=\"commPublishedSummaryCount\">6 published</span></div>\n          <div class=\"comms-published-grid\" id=\"commPublishedSummary\"></div>\n        </section>\n        <section class=\"comms-layout\">\n          <article class=\"panel comms-panel\">\n            <div class=\"comms-panel-head\"><div><span class=\"eyebrow\">PUBLISHER</span><h2>Create Communication</h2><p>Choose a category, audience and message content.</p></div><span class=\"comms-chip\"><svg class=\"icon\"><use href=\"#i-edit\"/></svg>Compose</span></div>\n            <div class=\"comms-form-grid\">\n              <div class=\"comms-field\"><label for=\"commCategory\">Front-page section</label><select id=\"commCategory\"><option value=\"Safety Alerts\">Safety Alerts</option><option value=\"Circulars &amp; Notices\">Circulars &amp; Notices</option><option value=\"Upcoming Events\">Upcoming Events</option></select></div>\n              <div class=\"comms-field\"><label for=\"commAudience\">Audience</label><select id=\"commAudience\"><option>All Employees</option><option>West Bokaro</option><option>Production</option><option>Maintenance</option><option>Transport</option><option>Contractors</option></select></div>\n              <div class=\"comms-field hidden\" id=\"commAlertTypeField\"><label for=\"commAlertType\">Safety alert type</label><select id=\"commAlertType\"><option value=\"\">Choose alert type</option><option>LTI</option><option>First Aid</option><option>Fatal</option><option>Red Risk</option><option>Medical Case</option><option>Burn Injury</option><option>Property Damage</option><option>Other</option></select></div>\n              <div class=\"comms-field hidden\" id=\"commContentKindField\"><label for=\"commContentKind\">Content type</label><select id=\"commContentKind\"><option>Notice</option><option>Circular</option></select></div>\n              <div class=\"comms-field full\"><label for=\"commTitle\">Title</label><input id=\"commTitle\" type=\"text\" maxlength=\"120\" placeholder=\"Enter a clear communication title\"/></div>\n              <div class=\"comms-field full hidden\" id=\"commEventDateField\"><label for=\"commEventDate\">Event date and time</label><input id=\"commEventDate\" type=\"datetime-local\"/><small class=\"comms-field-note\">Displayed in the Upcoming Events section on the employee front page.</small></div>\n              <div class=\"comms-field full\"><label for=\"commMessage\">Message text</label><textarea id=\"commMessage\" placeholder=\"Write the alert controls, notice, circular or event details...\"></textarea></div>\n              <div class=\"comms-field full\"><label>Attachments</label><div class=\"comms-attach-row\"><label class=\"comms-attach-button\" for=\"commFiles\"><svg class=\"icon\"><use href=\"#i-upload\"/></svg>Add file</label><input id=\"commFiles\" type=\"file\" class=\"hidden\" multiple accept=\"image/*,.txt,.text,.ppt,.pptx,.pdf,text/plain,application/pdf,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation\"/><div id=\"commFileList\" class=\"comms-file-list\"></div></div><small class=\"comms-field-note\">Accepted: images, text (.txt), PowerPoint (.ppt/.pptx), and PDF. Demo keeps attachment names only; file upload is configured later.</small></div>\n            </div>\n            <div class=\"comms-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"commSaveDraft\"><svg class=\"icon\"><use href=\"#i-file\"/></svg>Save Draft</button><button type=\"button\" class=\"btn btn-primary\" id=\"commPublish\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg>Release / Publish</button><button type=\"button\" class=\"btn comms-broadcast-button\" id=\"commBroadcast\"><svg class=\"icon\"><use href=\"#i-message\"/></svg>Broadcast Now</button></div>\n            <p class=\"comms-demo-hint\">Demo only: Publish and Broadcast update this preview. Real employee notifications and persistent attachment storage will be connected later.</p>\n          </article>\n          <article class=\"panel comms-panel\">\n            <div class=\"comms-panel-head\"><div><span class=\"eyebrow\">EMPLOYEE VIEW</span><h2>User Front Page Preview</h2><p>Currently released safety communications</p></div><span class=\"comms-chip\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg>Live preview</span></div>\n            <div class=\"comms-preview-head\"><div><strong>Employee Home</strong><small>Published cards in the user-facing front page</small></div><span id=\"commVisibleCount\" class=\"case-report-count\">4 live</span></div>\n            <div class=\"comms-preview-sections\" id=\"employeeFrontPagePreview\"></div>\n            <nav class=\"comms-user-bottom-nav\" aria-label=\"Employee front page bottom navigation\"><button type=\"button\" class=\"active\" data-comm-preview-category=\"All Communications\"><svg class=\"icon\"><use href=\"#i-dashboard\"/></svg>Home</button><button type=\"button\" data-comm-preview-category=\"Safety Alerts\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg>Safety Alerts</button><button type=\"button\" data-comm-preview-category=\"Circulars &amp; Notices\"><svg class=\"icon\"><use href=\"#i-file\"/></svg>Circulars &amp; Notices</button><button type=\"button\" data-comm-preview-category=\"Upcoming Events\"><svg class=\"icon\"><use href=\"#i-calendar\"/></svg>Upcoming Events</button></nav>\n            <div class=\"comms-preview-empty hidden\" id=\"commPreviewEmpty\">No communications have been released yet.</div>\n          </article>\n        </section>\n        <section class=\"panel comms-library\">\n          <div class=\"comms-panel-head\"><div><span class=\"eyebrow\">CONTENT MANAGEMENT</span><h2 id=\"commLibraryHeading\">All Communications</h2><p>Review drafts, release content and broadcast messages again.</p></div><span class=\"case-report-count\" id=\"commRecordCount\">5 items</span></div>\n          <div class=\"comms-category-tabs\" id=\"commCategoryTabs\" aria-label=\"Filter communications by type\">\n            <button type=\"button\" class=\"comms-category-tab active\" data-comm-category=\"All Communications\" aria-pressed=\"true\">All Communications</button>\n            <button type=\"button\" class=\"comms-category-tab\" data-comm-category=\"Safety Alerts\" aria-pressed=\"false\">Safety Alerts</button>\n            <button type=\"button\" class=\"comms-category-tab\" data-comm-category=\"Circulars &amp; Notices\" aria-pressed=\"false\">Circulars &amp; Notices</button>\n            <button type=\"button\" class=\"comms-category-tab\" data-comm-category=\"Upcoming Events\" aria-pressed=\"false\">Upcoming Events</button>\n          </div>\n          <div class=\"comms-list-toolbar\"><label class=\"comms-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"commSearch\" type=\"search\" placeholder=\"Search title or message...\"/></label><select id=\"commStatusFilter\" aria-label=\"Filter communication status\"><option value=\"\">All statuses</option><option>Draft</option><option>Published</option><option>Broadcast</option></select><span class=\"case-result-count\" id=\"commFilteredCount\">5 shown</span></div>\n          <div class=\"table-wrap\"><table class=\"comms-table\"><thead><tr><th>Front-page Section</th><th>Title / Message</th><th>Audience</th><th>Event / Release</th><th>Attachment</th><th>Status</th><th>Actions</th></tr></thead><tbody id=\"communicationsTableBody\"></tbody></table><div class=\"comms-empty hidden\" id=\"communicationsEmpty\">No communications match these filters.</div></div>\n        </section>\n      </main>\n\n      <main class=\"page hidden\" id=\"documentsPage\">\n        <section class=\"page-heading\">\n          <div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-folder\"/></svg></div><div><h1>Document Vault / Library</h1><p class=\"page-subtitle\">Browse, publish and manage documents shown in the employee front-page library</p></div></div>\n        </section>\n        <div class=\"doc-source-note\"><svg class=\"icon\"><use href=\"#i-book\"/></svg><div><strong>Employee Front Page · Documents &amp; Library</strong><small>The four front-page categories below open their matching document lists. Published files will appear in the employee-facing library preview.</small></div><span class=\"case-demo-badge\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg>Demo mode</span></div>\n        <section class=\"doc-stats-grid\" aria-label=\"Document library summary\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-file\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Documents</div><div class=\"stat-value\" id=\"docTotalCount\">8</div><div class=\"stat-period\">All categories</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Published</div><div class=\"stat-value\" id=\"docPublishedCount\">7</div><div class=\"stat-period\">Visible to employees</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clock\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Drafts</div><div class=\"stat-value\" id=\"docDraftCount\">1</div><div class=\"stat-period\">Not visible yet</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-purple\"><svg class=\"icon\"><use href=\"#i-book\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Front-page Categories</div><div class=\"stat-value\" id=\"docCategoryCount\">4</div><div class=\"stat-period\">Employee library sections</div></div></article>\n        </section>\n        <section class=\"doc-category-grid\" id=\"docCategoryCards\" aria-label=\"Employee front-page document categories\"></section>\n        <section class=\"panel doc-published-panel\" aria-live=\"polite\">\n          <div class=\"doc-published-head\"><div><span class=\"eyebrow\">EMPLOYEE-FACING CONTENT</span><h2>Published Document Summary</h2><p>What employees can currently find in each library category.</p></div><span class=\"case-report-count\" id=\"docPublishedSummaryCount\">7 published</span></div>\n          <div class=\"doc-published-grid\" id=\"docPublishedSummary\"></div>\n        </section>\n        <section class=\"panel doc-composer\">\n          <div class=\"doc-panel-head\"><div><span class=\"eyebrow\">PUBLISHER</span><h2>Add a Document</h2><p>Add a new item to one of the employee front-page library categories.</p></div><span class=\"comms-chip\"><svg class=\"icon\"><use href=\"#i-upload\"/></svg>Compose</span></div>\n          <div class=\"doc-form-grid\">\n            <div class=\"doc-field span2\"><label for=\"docCategory\">Front-page category</label><select id=\"docCategory\"><option value=\"SOP / SWP\">SOP / SWP</option><option value=\"Risk Assessments\">Risk Assessments</option><option value=\"Legal &amp; Statutory Compliance\">Legal &amp; Statutory Compliance</option><option value=\"Policy &amp; Procedures\">Policy &amp; Procedures</option></select></div>\n            <div class=\"doc-field\"><label for=\"docCode\">Document code</label><input id=\"docCode\" type=\"text\" maxlength=\"32\" placeholder=\"e.g. SOP-HSE-014\"/></div>\n            <div class=\"doc-field\"><label for=\"docVersion\">Version</label><input id=\"docVersion\" type=\"text\" maxlength=\"20\" placeholder=\"e.g. 1.0\"/></div>\n            <div class=\"doc-field span2\"><label for=\"docTitle\">Document title</label><input id=\"docTitle\" type=\"text\" maxlength=\"140\" placeholder=\"Enter the document title\"/></div>\n            <div class=\"doc-field\"><label for=\"docEffectiveDate\">Effective / review date</label><input id=\"docEffectiveDate\" type=\"date\"/></div>\n            <div class=\"doc-field\"><label for=\"docAudience\">Audience</label><select id=\"docAudience\"><option>All Employees</option><option>West Bokaro</option><option>Production</option><option>Maintenance</option><option>Transport</option><option>Contractors</option></select></div>\n            <div class=\"doc-field full\"><label for=\"docDescription\">Summary / key details</label><textarea id=\"docDescription\" placeholder=\"Describe what this document covers and who should use it.\"></textarea></div>\n            <div class=\"doc-field full\"><label>Files</label><div class=\"doc-attach-row\"><label class=\"doc-attach-button\" for=\"docFiles\"><svg class=\"icon\"><use href=\"#i-upload\"/></svg>Add file(s)</label><input id=\"docFiles\" type=\"file\" class=\"hidden\" multiple accept=\"image/*,.pdf,.ppt,.pptx,.doc,.docx,.xls,.xlsx,.txt,.csv,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/plain,text/csv\"/><div class=\"doc-file-list\" id=\"docFileList\"></div></div><small class=\"doc-field-note\">Accepted: PDF, images, PowerPoint, Word, Excel, text and CSV. Demo stores file names only; actual upload/storage is for the later backend connection.</small></div>\n          </div>\n          <div class=\"doc-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"docSaveDraft\"><svg class=\"icon\"><use href=\"#i-file\"/></svg>Save Draft</button><button type=\"button\" class=\"btn btn-primary\" id=\"docPublish\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg>Publish to Employee Library</button></div>\n          <p class=\"doc-demo-hint\">Demo only: publishing updates the summary and front-page library preview in this page. Persistent file storage and live employee delivery will be connected later.</p>\n        </section>\n        <section class=\"panel doc-library-panel\">\n          <div class=\"doc-panel-head\"><div><span class=\"eyebrow\">CONTENT MANAGEMENT</span><h2 id=\"docLibraryHeading\">All Documents</h2><p>View, edit, delete or publish documents by category.</p></div><span class=\"case-report-count\" id=\"docRecordCount\">8 items</span></div>\n          <div class=\"doc-category-tabs\" id=\"docCategoryTabs\" aria-label=\"Filter documents by category\"></div>\n          <div class=\"doc-list-toolbar\"><label class=\"doc-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"docSearch\" type=\"search\" placeholder=\"Search title, code, category or details...\"/></label><select id=\"docStatusFilter\" aria-label=\"Filter document status\"><option value=\"\">All statuses</option><option>Draft</option><option>Published</option></select><span class=\"case-result-count\" id=\"docFilteredCount\">8 shown</span></div>\n          <div class=\"table-wrap\"><table class=\"doc-table\"><thead><tr><th>Category</th><th>Document</th><th>Version</th><th>Effective Date</th><th>Files</th><th>Status</th><th>Actions</th></tr></thead><tbody id=\"docTableBody\"></tbody></table><div class=\"doc-empty hidden\" id=\"docEmpty\">No documents match these filters.</div></div>\n        </section>\n      </main>\n\n      <main class=\"page hidden\" id=\"auditInspectionHomePage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div><h1>Audit &amp; Inspection</h1><p class=\"page-subtitle\">Plan audits, record inspections and build reusable safety forms</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg><div><strong>Audit &amp; Inspection Workspace</strong><small>Audit Form, Inspection Form and Form Builder are grouped here. Demo records can be refined before the Supabase connection.</small></div><span class=\"case-demo-badge\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg>Demo mode</span></div>\n        <section class=\"ai-summary-grid\" aria-label=\"Audit and inspection overview\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Audits</div><div class=\"stat-value\" id=\"aiTotalAudits\">5</div><div class=\"stat-period\">All audit records</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Inspections</div><div class=\"stat-value\" id=\"aiTotalInspections\">5</div><div class=\"stat-period\">All inspection records</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Open Actions</div><div class=\"stat-value\" id=\"aiOpenActions\">0</div><div class=\"stat-period\">Audit and inspection follow-up</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-purple\"><svg class=\"icon\"><use href=\"#i-layout\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Published Templates</div><div class=\"stat-value\" id=\"aiPublishedTemplates\">2</div><div class=\"stat-period\">Reusable form templates</div></div></article>\n        </section>\n        <section class=\"ai-dashboard-grid\" aria-label=\"Audit and inspection sections\">\n          <button type=\"button\" class=\"ai-dashboard-card\" data-ai-page=\"audit\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></span><h2>Audit Form</h2></span><p>Plan a safety audit, record the scope and findings, and track corrective actions.</p><span class=\"ai-dashboard-card-foot\"><span id=\"aiHomeAuditCount\">5 audit records</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-ai-page=\"inspection\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-shield-alert\"/></svg></span><h2>Inspection Form</h2></span><p>Inspect equipment or work areas, record condition and assign follow-up actions.</p><span class=\"ai-dashboard-card-foot\"><span id=\"aiHomeInspectionCount\">5 inspection records</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-ai-page=\"builder\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-layout\"/></svg></span><h2>Form Builder</h2></span><p>Create reusable audit and inspection templates with required fields and dropdowns.</p><span class=\"ai-dashboard-card-foot\"><span>Build or manage templates</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n        </section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">RECENT ACTIVITY</span><h2>Latest Audit &amp; Inspection Records</h2><p>Sample records from the demo workspace.</p></div></div><div class=\"table-wrap\"><table class=\"ai-table\"><thead><tr><th>Record</th><th>Type</th><th>Site / Area</th><th>Date</th><th>Status</th><th>Open Actions</th></tr></thead><tbody id=\"aiRecentActivity\"></tbody></table></div></section>\n      </main>\n\n      <main class=\"page hidden\" id=\"auditFormPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div><h1>Audit Form</h1><p class=\"page-subtitle\">Record audit scope, findings and corrective-action follow-up</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg><div><strong>Safety Audit Register</strong><small>Demo workflow: plan an audit, log findings and maintain action owners and due dates.</small></div><span class=\"case-demo-badge\">Demo records</span></div>\n        <section class=\"ai-summary-grid\" aria-label=\"Audit summary\"><article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Audits</div><div class=\"stat-value\" id=\"auditTotalCount\">5</div><div class=\"stat-period\">All audit types</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clock\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Planned / Active</div><div class=\"stat-value\" id=\"auditActiveCount\">0</div><div class=\"stat-period\">Open for review</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-red\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Findings</div><div class=\"stat-value\" id=\"auditFindingCount\">0</div><div class=\"stat-period\">Logged across audits</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Completed</div><div class=\"stat-value\" id=\"auditCompletedCount\">0</div><div class=\"stat-period\">Closed / completed audits</div></div></article></section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">NEW AUDIT</span><h2>Audit Details &amp; Findings</h2><p>Choose an audit form and complete its category-specific checklist.</p></div></div>\n          <div class=\"ai-type-tabs\" id=\"auditFormCategoryChips\" aria-label=\"Choose an audit form\"></div>\n          <div class=\"ai-checklist-panel\"><div class=\"ai-checklist-head\"><div><strong id=\"auditChecklistTitle\">PPE Audit Checklist</strong><small>Mark each item. Needs Action / Fail entries are counted as findings.</small></div><span id=\"auditChecklistCount\" class=\"case-report-count\">0 findings</span></div><div class=\"ai-checklist-list\" id=\"auditChecklistBody\"></div></div>\n          <div class=\"ai-form-grid\"><div class=\"ai-field span2\"><label for=\"auditTitle\">Audit title</label><input id=\"auditTitle\" maxlength=\"120\" placeholder=\"e.g. PPE compliance audit\"/></div><div class=\"ai-field\"><label for=\"auditType\">Audit form</label><select id=\"auditType\"><option>PPE</option><option>Tool Tackles</option><option>Lifting Tool</option><option>Housekeeping</option><option>Store Audit</option></select></div><div class=\"ai-field\"><label for=\"auditDate\">Audit date</label><input id=\"auditDate\" type=\"date\" value=\"2026-10-04\"/></div><div class=\"ai-field\"><label for=\"auditSite\">Site / location</label><select id=\"auditSite\"><option>West Bokaro</option><option>Scrap Yard</option><option>Transport Park</option><option>Bog Area</option><option>Workshop</option><option>Other</option></select></div><div class=\"ai-field\"><label for=\"auditDepartment\">Department</label><select id=\"auditDepartment\"><option>Production</option><option>Maintenance</option><option>Transport</option><option>Contractor</option><option>Admin</option><option>HSE</option></select></div><div class=\"ai-field\"><label for=\"auditAuditor\">Auditor / lead</label><input id=\"auditAuditor\" value=\"Rakesh Kumar\"/></div><div class=\"ai-field\"><label for=\"auditPriority\">Highest finding priority</label><select id=\"auditPriority\"><option>Low</option><option selected>Medium</option><option>High</option><option>Critical</option></select></div><div class=\"ai-field\"><label for=\"auditFindingNumber\">Checklist findings</label><input id=\"auditFindingNumber\" type=\"number\" min=\"0\" value=\"0\" readonly/></div><div class=\"ai-field\"><label for=\"auditStatus\">Status</label><select id=\"auditStatus\"><option>Planned</option><option selected>In Progress</option><option>Completed</option><option>Closed</option></select></div><div class=\"ai-field full\"><label for=\"auditScope\">Scope / checklist covered</label><textarea id=\"auditScope\" placeholder=\"e.g. PPE, housekeeping, permit-to-work, machine guarding\"></textarea></div><div class=\"ai-field span2\"><label for=\"auditFindingDetails\">Findings / observations</label><textarea id=\"auditFindingDetails\" placeholder=\"Summarize non-conformances or positive observations\"></textarea></div><div class=\"ai-field span2\"><label for=\"auditCorrectiveAction\">Corrective action / owner / due date</label><textarea id=\"auditCorrectiveAction\" placeholder=\"Action, responsible person and target date\"></textarea></div></div>\n          <div class=\"ai-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"auditReset\">Reset</button><button type=\"button\" class=\"btn btn-primary\" id=\"auditSave\">Save Audit</button></div>\n        </section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">AUDIT REGISTER</span><h2>Audit Records</h2><p>Search and manage the demo audit register.</p></div><span class=\"case-report-count\" id=\"auditRecordCount\">5 records</span></div><div class=\"ai-toolbar\"><label class=\"ai-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"auditSearch\" type=\"search\" placeholder=\"Search audit ID, title, auditor or site...\"/></label><select id=\"auditStatusFilter\" aria-label=\"Filter audit status\"><option value=\"\">All statuses</option><option>Planned</option><option>In Progress</option><option>Completed</option><option>Closed</option></select><span class=\"case-result-count\" id=\"auditFilteredCount\">5 shown</span></div><div class=\"table-wrap\"><table class=\"ai-table\"><thead><tr><th>Audit ID</th><th>Audit / Type</th><th>Site / Department</th><th>Auditor</th><th>Date</th><th>Findings</th><th>Status</th><th>Actions</th></tr></thead><tbody id=\"auditTableBody\"></tbody></table><div class=\"ai-empty hidden\" id=\"auditEmpty\">No audits match these filters.</div></div></section>\n      </main>\n\n      <main class=\"page hidden\" id=\"inspectionFormPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-shield-alert\"/></svg></div><div><h1>Inspection Form</h1><p class=\"page-subtitle\">Inspect equipment and work areas, record defects and assign follow-up</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-shield-alert\"/></svg><div><strong>Safety Inspection Register</strong><small>Demo workflow: record pass/fail conditions, defects, responsible actions and target dates.</small></div><span class=\"case-demo-badge\">Demo records</span></div>\n        <section class=\"ai-summary-grid\" aria-label=\"Inspection summary\"><article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Inspections</div><div class=\"stat-value\" id=\"inspectionTotalCount\">5</div><div class=\"stat-period\">All inspection types</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Passed</div><div class=\"stat-value\" id=\"inspectionPassCount\">0</div><div class=\"stat-period\">Safe / acceptable condition</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-red\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Needs Action</div><div class=\"stat-value\" id=\"inspectionActionCount\">0</div><div class=\"stat-period\">Findings requiring follow-up</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clock\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Open Actions</div><div class=\"stat-value\" id=\"inspectionOpenCount\">0</div><div class=\"stat-period\">Not yet closed</div></div></article></section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">NEW INSPECTION</span><h2>Inspection Details &amp; Condition</h2><p>Select a checklist and record the inspected vehicle or extinguisher.</p></div></div>\n          <div class=\"ai-type-tabs\" id=\"inspectionFormCategoryChips\" aria-label=\"Choose an inspection form\"></div>\n          <div class=\"ai-checklist-panel\"><div class=\"ai-checklist-head\"><div><strong id=\"inspectionChecklistTitle\">Vehicle Inspection Checklist</strong><small>Mark each item. Overall result is calculated from the checklist.</small></div><span id=\"inspectionChecklistCount\" class=\"case-report-count\">0 checked</span></div><div class=\"ai-checklist-list\" id=\"inspectionChecklistBody\"></div></div>\n          <div class=\"ai-form-grid\"><div class=\"ai-field span2\"><label for=\"inspectionAsset\">Asset / area inspected</label><input id=\"inspectionAsset\" maxlength=\"120\" placeholder=\"e.g. Vehicle registration / fleet ID\"/></div><div class=\"ai-field\"><label for=\"inspectionType\">Inspection form</label><select id=\"inspectionType\"><option>Vehicle Inspection</option><option>Fire Extinguisher</option></select></div><div class=\"ai-field\"><label for=\"inspectionDate\">Inspection date</label><input id=\"inspectionDate\" type=\"date\" value=\"2026-10-04\"/></div><div class=\"ai-field\"><label for=\"inspectionSite\">Site / location</label><select id=\"inspectionSite\"><option>West Bokaro</option><option>Scrap Yard</option><option>Transport Park</option><option>Bog Area</option><option>Workshop</option><option>Other</option></select></div><div class=\"ai-field\"><label for=\"inspectionDepartment\">Department</label><select id=\"inspectionDepartment\"><option>Production</option><option>Maintenance</option><option>Transport</option><option>Contractor</option><option>Admin</option><option>HSE</option></select></div><div class=\"ai-field\"><label for=\"inspectionInspector\">Inspector</label><input id=\"inspectionInspector\" value=\"Amit Kumar\"/></div><div class=\"ai-field\"><label for=\"inspectionResult\">Overall result · automatic</label><select id=\"inspectionResult\" disabled><option>Not Assessed</option><option>Pass</option><option>Needs Action</option><option>Fail</option></select></div><div class=\"ai-field\"><label for=\"inspectionPriority\">Priority</label><select id=\"inspectionPriority\"><option>Low</option><option>Medium</option><option selected>High</option><option>Critical</option></select></div><div class=\"ai-field\"><label for=\"inspectionDueDate\">Action due date</label><input id=\"inspectionDueDate\" type=\"date\"/></div><div class=\"ai-field\"><label for=\"inspectionStatus\">Action status</label><select id=\"inspectionStatus\"><option>Open</option><option>In Progress</option><option>Closed</option></select></div><div class=\"ai-field full\"><label for=\"inspectionCondition\">Condition / findings</label><textarea id=\"inspectionCondition\" placeholder=\"Describe condition, defects or safe observations\"></textarea></div><div class=\"ai-field full\"><label for=\"inspectionCorrectiveAction\">Corrective action / owner</label><textarea id=\"inspectionCorrectiveAction\" placeholder=\"Action required, responsible person and due date\"></textarea></div></div>\n          <div class=\"ai-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"inspectionReset\">Reset</button><button type=\"button\" class=\"btn btn-primary\" id=\"inspectionSave\">Save Inspection</button></div>\n        </section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">INSPECTION REGISTER</span><h2>Inspection Records</h2><p>Search and manage the demo inspection register.</p></div><span class=\"case-report-count\" id=\"inspectionRecordCount\">5 records</span></div><div class=\"ai-toolbar\"><label class=\"ai-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"inspectionSearch\" type=\"search\" placeholder=\"Search asset, inspection ID, inspector or site...\"/></label><select id=\"inspectionStatusFilter\" aria-label=\"Filter inspection status\"><option value=\"\">All action statuses</option><option>Open</option><option>In Progress</option><option>Closed</option></select><span class=\"case-result-count\" id=\"inspectionFilteredCount\">5 shown</span></div><div class=\"table-wrap\"><table class=\"ai-table\"><thead><tr><th>Inspection ID</th><th>Asset / Type</th><th>Site / Department</th><th>Inspector</th><th>Date</th><th>Result</th><th>Action Status</th><th>Actions</th></tr></thead><tbody id=\"inspectionTableBody\"></tbody></table><div class=\"ai-empty hidden\" id=\"inspectionEmpty\">No inspections match these filters.</div></div></section>\n      </main>\n\n      <main class=\"page hidden\" id=\"formBuilderPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-layout\"/></svg></div><div><h1>Form Builder</h1><p class=\"page-subtitle\">Build reusable custom forms for Audit and Inspection workflows</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-layout\"/></svg><div><strong>Reusable Form Templates</strong><small>Add common field types, set required fields and preview the form before saving it.</small></div><span class=\"case-demo-badge\">Demo builder</span></div>\n        <section class=\"ai-builder-layout\">\n          <article class=\"panel ai-panel ai-builder-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">FORM DESIGNER</span><h2 id=\"builderPanelTitle\">Create a Form Template</h2><p>Set a template name, choose where it is used, then add fields.</p></div><button type=\"button\" class=\"btn btn-light btn-small\" id=\"builderReset\">New / Reset</button></div>\n            <div class=\"ai-form-grid\"><div class=\"ai-field span2\"><label for=\"builderTemplateName\">Template name</label><input id=\"builderTemplateName\" maxlength=\"100\" placeholder=\"e.g. Weekly Workplace Audit\"/></div><div class=\"ai-field span2\"><label for=\"builderTarget\">Use this form for</label><select id=\"builderTarget\"><option>Audit</option><option>Inspection</option></select></div></div>\n            <div class=\"ai-builder-inline\"><div class=\"ai-field\"><label for=\"builderFieldLabel\">New field label</label><input id=\"builderFieldLabel\" placeholder=\"e.g. Emergency exit clear?\"/></div><div class=\"ai-field\"><label for=\"builderFieldType\">Field type</label><select id=\"builderFieldType\"><option>Short text</option><option>Long text</option><option>Number</option><option>Date</option><option>Yes / No</option><option>Dropdown</option><option>Checkbox</option></select></div></div>\n            <div class=\"ai-field\"><label for=\"builderFieldOptions\">Dropdown options <span class=\"ai-help\">Only used for Dropdown fields; separate choices with commas.</span></label><input id=\"builderFieldOptions\" placeholder=\"e.g. Good, Needs Action, Not Applicable\"/></div>\n            <label class=\"radio-wrap\" style=\"margin-top:8px\"><span><input id=\"builderFieldRequired\" type=\"checkbox\" checked/> Required field</span></label>\n            <div class=\"ai-form-actions\" style=\"justify-content:flex-start\"><button type=\"button\" class=\"btn btn-soft\" id=\"builderAddField\"><svg class=\"icon\"><use href=\"#i-plus\"/></svg>Add Field</button><span class=\"case-result-count\" id=\"builderFieldCount\">0 fields</span></div>\n            <div id=\"builderFieldList\" class=\"ai-builder-field-list\"></div>\n            <div class=\"ai-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"builderSaveDraft\">Save as Draft</button><button type=\"button\" class=\"btn btn-primary\" id=\"builderPublish\">Publish Template</button></div>\n          </article>\n          <article class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">LIVE PREVIEW</span><h2 id=\"builderPreviewTitle\">Form preview</h2><p id=\"builderPreviewTarget\">Audit template</p></div><span class=\"comms-chip\">Preview</span></div><div class=\"ai-preview-form\" id=\"builderPreview\"></div></article>\n        </section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">TEMPLATE LIBRARY</span><h2>Saved Templates</h2><p>Manage templates used for audit and inspection workflows.</p></div><span class=\"case-report-count\" id=\"builderTemplateCount\">3 templates</span></div><div class=\"table-wrap\"><table class=\"ai-table ai-template-table\"><thead><tr><th>Template ID</th><th>Template</th><th>Used For</th><th>Fields</th><th>Updated</th><th>Status</th><th>Actions</th></tr></thead><tbody id=\"builderTemplateBody\"></tbody></table><div class=\"ai-empty hidden\" id=\"builderTemplateEmpty\">No templates match your workspace.</div></div></section>\n        <p class=\"doc-demo-hint\">Demo only: saved templates are kept in this page session. Hooking the builder to production form storage comes with the later Supabase integration.</p>\n      </main>\n\n      <main class=\"page hidden\" id=\"dmPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-folder\"/></svg></div><div><h1>DM</h1><p class=\"page-subtitle\">Dedicated workspace placeholder</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-folder\"/></svg><div><strong>DM Workspace</strong><small>This section is ready for the workflow and tools you want to add.</small></div><span class=\"case-demo-badge\">Demo placeholder</span></div>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">WORKSPACE</span><h2>DM section is ready</h2><p>Tell me what DM should include, and this page can be built out without changing your other dashboard sections.</p></div></div></section>\n      </main>\n\n      <main class=\"page hidden\" id=\"userAccessPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-users\"/></svg></div><div><h1>User &amp; Access Management</h1><p class=\"page-subtitle\">Create users, assign roles and grant or remove workspace permissions</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-users\"/></svg><div><strong>Workspace Access Control</strong><small>Manage demo user accounts, role presets, module access and individual actions.</small></div><span class=\"case-demo-badge\">Demo mode</span></div>\n        <div class=\"ua-security-note\"><strong>Security note:</strong> User and permission management is still a front-end demo. Passwords entered here are checked and discarded; they are not sent to Supabase or stored. The separate Supabase Auth adapter only supports sign-in, sign-out and password change.</div>\n        <section class=\"ai-summary-grid\" aria-label=\"User access summary\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-users\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Users</div><div class=\"stat-value\" id=\"uaTotalUsers\">0</div><div class=\"stat-period\">Demo user list</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Active Users</div><div class=\"stat-value\" id=\"uaActiveUsers\">0</div><div class=\"stat-period\">Marked active in demo</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-purple\"><svg class=\"icon\"><use href=\"#i-shield\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Administrators</div><div class=\"stat-value\" id=\"uaAdminUsers\">0</div><div class=\"stat-period\">Assigned admin role</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-shield-alert\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Permission Grants</div><div class=\"stat-value\" id=\"uaPermissionGrants\">0</div><div class=\"stat-period\">Across the user list</div></div></article>\n        </section>\n        <section class=\"panel ai-panel\" id=\"uaUserFormPanel\">\n          <div class=\"ai-panel-head\"><div><span class=\"eyebrow\">USER ACCOUNT</span><h2 id=\"uaFormTitle\">Create a User</h2><p>Set a username and role, then customize what this account can access.</p></div><span class=\"comms-chip\">Create / Edit</span></div>\n          <form id=\"uaUserForm\" novalidate>\n            <div class=\"ai-form-grid\">\n              <div class=\"ai-field span2\"><label for=\"uaDisplayName\">Display name</label><input id=\"uaDisplayName\" maxlength=\"80\" placeholder=\"e.g. Rakesh Kumar\"/></div>\n              <div class=\"ai-field\"><label for=\"uaUsername\">Username <span class=\"required\">*</span></label><input id=\"uaUsername\" required minlength=\"3\" maxlength=\"32\" pattern=\"[A-Za-z0-9._-]+\" autocomplete=\"off\" placeholder=\"e.g. rakesh.kumar\"/></div>\n              <div class=\"ai-field\"><label for=\"uaRole\">Role <span class=\"required\">*</span></label><select id=\"uaRole\" required><option>Administrator</option><option>Safety Officer</option><option>Manager</option><option>Supervisor</option><option>Viewer</option><option>Custom</option></select></div>\n              <div class=\"ai-field\"><label for=\"uaStatus\">Account status</label><select id=\"uaStatus\"><option>Active</option><option>Inactive</option></select></div>\n              <div class=\"ai-field\"><label for=\"uaPassword\">Password <span id=\"uaPasswordRequired\" class=\"required\">*</span></label><input id=\"uaPassword\" type=\"password\" minlength=\"8\" autocomplete=\"new-password\" placeholder=\"At least 8 characters\"/><small class=\"ua-form-note\" id=\"uaPasswordHelp\">Required for a new demo user. The value is never saved.</small></div>\n              <div class=\"ai-field\"><label for=\"uaPasswordConfirm\">Confirm password <span id=\"uaConfirmRequired\" class=\"required\">*</span></label><input id=\"uaPasswordConfirm\" type=\"password\" minlength=\"8\" autocomplete=\"new-password\" placeholder=\"Re-enter password\"/></div>\n            </div>\n            <div class=\"ai-panel-head\" style=\"margin:12px 0 6px\"><div><span class=\"eyebrow\">PERMISSION ASSIGNMENT</span><h2>Module permissions</h2><p>Select the actions this user may perform. Unchecked actions are not granted.</p></div></div>\n            <div class=\"ua-permission-tools\"><p id=\"uaPermissionPresetNote\">Role permissions are suggested defaults; adjust individual actions before saving.</p><div class=\"ua-permission-buttons\"><button type=\"button\" class=\"btn btn-light\" id=\"uaApplyRoleDefaults\">Apply role defaults</button><button type=\"button\" class=\"btn btn-light\" id=\"uaGrantAll\">Grant all</button><button type=\"button\" class=\"btn btn-light\" id=\"uaClearAll\">Clear all</button></div></div>\n            <div class=\"table-wrap\" id=\"uaPermissionMatrix\"><table class=\"ai-table ua-permission-table\"><thead><tr><th scope=\"col\">Sidebar module</th><th scope=\"col\">View</th><th scope=\"col\">Create</th><th scope=\"col\">Edit</th><th scope=\"col\">Delete</th><th scope=\"col\">Publish</th><th scope=\"col\">Export</th></tr></thead><tbody id=\"uaPermissionRows\"></tbody></table></div>\n            <div class=\"ai-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"uaResetForm\">Clear form</button><button type=\"submit\" class=\"btn btn-primary\" id=\"uaSaveUser\">Create User</button></div>\n          </form>\n        </section>\n        <section class=\"panel ai-panel\">\n          <div class=\"ai-panel-head\"><div><span class=\"eyebrow\">USER DIRECTORY</span><h2>Managed Users</h2><p>Review accounts and edit roles or permissions at any time.</p></div><span class=\"case-report-count\" id=\"uaUserCount\">0 users</span></div>\n          <div class=\"ai-toolbar\"><label class=\"ai-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"uaSearch\" type=\"search\" placeholder=\"Search username, name or role...\"/></label><select id=\"uaRoleFilter\" aria-label=\"Filter by role\"><option value=\"\">All roles</option><option>Administrator</option><option>Safety Officer</option><option>Manager</option><option>Supervisor</option><option>Viewer</option><option>Custom</option></select><select id=\"uaStatusFilter\" aria-label=\"Filter account status\"><option value=\"\">All statuses</option><option>Active</option><option>Inactive</option></select><span class=\"case-result-count\" id=\"uaFilteredCount\">0 shown</span></div>\n          <div class=\"table-wrap\"><table class=\"ai-table ua-user-table\"><thead><tr><th>User / Username</th><th>Role</th><th>Permission grants</th><th>Password</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody id=\"uaUserTableBody\"></tbody></table><div class=\"ua-empty hidden\" id=\"uaUserEmpty\">No users match these filters.</div></div>\n        </section>\n        <p class=\"doc-demo-hint\">Demo only: user records and permission changes remain in this page session. Password values entered here are discarded. Supabase sign-in is configured separately in auth-config.js; this page does not create production accounts.</p>\n      </main>\n\n      <main class=\"page hidden\" id=\"dashboardPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-dashboard\"/></svg></div><div><h1>Dashboard</h1><p class=\"page-subtitle\">SafetyOS workspace overview and shortcuts</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-dashboard\"/></svg><div><strong>Workspace Snapshot</strong><small>Open any module below to review records and continue work.</small></div><span class=\"case-demo-badge\">Demo data</span></div>\n        <section class=\"ai-summary-grid\" aria-label=\"Workspace dashboard summary\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-cap\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Trainings</div><div class=\"stat-value\" id=\"dashTrainingCount\">128</div><div class=\"stat-period\">Month-filtered in Training Management</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-red\"><svg class=\"icon\"><use href=\"#i-briefcase\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Safety Reports</div><div class=\"stat-value\" id=\"dashCaseCount\">10</div><div class=\"stat-period\">Employee-front-page submissions</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Audits &amp; Inspections</div><div class=\"stat-value\" id=\"dashAiCount\">10</div><div class=\"stat-period\">Registers and demo records</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Published Content</div><div class=\"stat-value\" id=\"dashPublishedCount\">0</div><div class=\"stat-period\">Communications and library</div></div></article>\n        </section>\n        <section class=\"ai-dashboard-grid\" aria-label=\"Dashboard module shortcuts\">\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-nav=\"Training Management\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-cap\"/></svg></span><h2>Training Management</h2></span><p>Training entry, bulk entry, directory, materials and employee training records.</p><span class=\"ai-dashboard-card-foot\"><span>Open training workspace</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-nav=\"Case Management\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-briefcase\"/></svg></span><h2>Case Management</h2></span><p>Review near misses, observations, hazards and employee reports.</p><span class=\"ai-dashboard-card-foot\"><span>Review reports</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-nav=\"Communications\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-message\"/></svg></span><h2>Communications</h2></span><p>Manage safety alerts, circulars, notices and events.</p><span class=\"ai-dashboard-card-foot\"><span>Manage communications</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-nav=\"Documents & Library\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-book\"/></svg></span><h2>Documents &amp; Library</h2></span><p>Publish and manage the employee document library.</p><span class=\"ai-dashboard-card-foot\"><span>Open document library</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-nav=\"Audit & Inspection\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></span><h2>Audit &amp; Inspection</h2></span><p>Complete category-specific checklists and manage action follow-up.</p><span class=\"ai-dashboard-card-foot\"><span>Open audit workspace</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-nav=\"User & Access\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-users\"/></svg></span><h2>User &amp; Access</h2></span><p>Create demo accounts and assign role and module permissions.</p><span class=\"ai-dashboard-card-foot\"><span>Manage access</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n        </section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">RECENT WORKSPACE ACTIVITY</span><h2>Latest Records</h2><p>Recent sample activity across reporting and audit workflows.</p></div></div><div class=\"table-wrap\"><table class=\"ai-table\"><thead><tr><th>Record</th><th>Module</th><th>Site / Area</th><th>Date</th><th>Status</th></tr></thead><tbody id=\"dashboardActivityRows\"></tbody></table></div></section>\n      </main>\n\n      <main class=\"page hidden\" id=\"analyticsPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-chart\"/></svg></div><div><h1>View &amp; Analytics</h1><p class=\"page-subtitle\">Cross-module operational summary</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-chart\"/></svg><div><strong>Safety Operations Overview</strong><small>Counts are calculated from current demo registers. Training's month-filterable trend remains in Training Management.</small></div><span class=\"case-demo-badge\">Demo overview</span></div>\n        <section class=\"ai-summary-grid\" aria-label=\"Operations overview\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-briefcase\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Reports Logged</div><div class=\"stat-value\" id=\"overviewReports\">0</div><div class=\"stat-period\">Case Management</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-red\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Open Safety Actions</div><div class=\"stat-value\" id=\"overviewActions\">0</div><div class=\"stat-period\">Case, audit and inspection follow-up</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Published Content</div><div class=\"stat-value\" id=\"overviewPublished\">0</div><div class=\"stat-period\">Employee-facing content</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-purple\"><svg class=\"icon\"><use href=\"#i-folder\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Tracked Modules</div><div class=\"stat-value\" id=\"overviewModules\">0</div><div class=\"stat-period\">With current demo records</div></div></article>\n        </section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">MODULE SUMMARY</span><h2>Current Workload by Module</h2><p>This page is a text-and-table overview; no training analytics or pie charts are added here.</p></div><button type=\"button\" class=\"btn btn-light btn-small\" data-jump-nav=\"Training Management\">Open Training Management</button></div><div class=\"table-wrap\"><table class=\"ai-table\"><thead><tr><th>Module</th><th>Records / Items</th><th>Open / Draft</th><th>Current note</th></tr></thead><tbody id=\"overviewModuleRows\"></tbody></table></div></section>\n      </main>\n\n      <main class=\"page hidden\" id=\"certificatesPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-award\"/></svg></div><div><h1>Certificates</h1><p class=\"page-subtitle\">Review demo training certificates, validity and expiry status</p></div></div><button type=\"button\" class=\"btn btn-light btn-small\" id=\"certExportCsv\"><svg class=\"icon\"><use href=\"#i-download\"/></svg>Export CSV</button></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-award\"/></svg><div><strong>Training Certificate Register</strong><small>Sample certificate records for review. Issuance and verification remain demo-only.</small></div><span class=\"case-demo-badge\">Demo records</span></div>\n        <section class=\"ai-summary-grid\" aria-label=\"Certificate summary\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-file\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Total Certificates</div><div class=\"stat-value\" id=\"certTotal\">0</div><div class=\"stat-period\">Sample register</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Valid</div><div class=\"stat-value\" id=\"certValid\">0</div><div class=\"stat-period\">Within validity period</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clock\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Expiring Soon</div><div class=\"stat-value\" id=\"certExpiring\">0</div><div class=\"stat-period\">Due within 30 days</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-red\"><svg class=\"icon\"><use href=\"#i-alert\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Expired</div><div class=\"stat-value\" id=\"certExpired\">0</div><div class=\"stat-period\">Renewal may be required</div></div></article>\n        </section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">CERTIFICATE DIRECTORY</span><h2>Employee Certificates</h2><p>Search records, review certificate details or export the demo certificate record.</p></div><span class=\"case-report-count\" id=\"certRecordCount\">0 certificates</span></div><div class=\"ai-toolbar\"><label class=\"ai-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"certSearch\" type=\"search\" placeholder=\"Search employee, course or certificate ID...\"/></label><select id=\"certStatusFilter\" aria-label=\"Filter certificate status\"><option value=\"\">All statuses</option><option>Valid</option><option>Expiring Soon</option><option>Expired</option></select><span class=\"case-result-count\" id=\"certFilteredCount\">0 shown</span></div><div class=\"table-wrap\"><table class=\"ai-table\"><thead><tr><th>Certificate ID</th><th>Employee</th><th>Training</th><th>Issued</th><th>Valid Until</th><th>Status</th><th>Actions</th></tr></thead><tbody id=\"certTableBody\"></tbody></table><div class=\"ai-empty hidden\" id=\"certEmpty\">No certificates match these filters.</div></div></section>\n      </main>\n\n      <main class=\"page hidden\" id=\"exportReportsPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-file\"/></svg></div><div><h1>Export Reports</h1><p class=\"page-subtitle\">Download reports and data snapshots from the demo workspace</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-download\"/></svg><div><strong>Local Demo Exports</strong><small>Downloads are generated in your browser. No report is uploaded to a server.</small></div><span class=\"case-demo-badge\">Export center</span></div>\n        <section class=\"ai-summary-grid\" aria-label=\"Export center summary\">\n          <article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-cap\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Training Topics</div><div class=\"stat-value\" id=\"exportTrainingCount\">0</div><div class=\"stat-period\">Directory rows</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-red\"><svg class=\"icon\"><use href=\"#i-briefcase\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Case Reports</div><div class=\"stat-value\" id=\"exportCaseCount\">0</div><div class=\"stat-period\">Case Management</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Audit + Inspection</div><div class=\"stat-value\" id=\"exportAuditCount\">0</div><div class=\"stat-period\">Combined register rows</div></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-book\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Library Documents</div><div class=\"stat-value\" id=\"exportDocumentCount\">0</div><div class=\"stat-period\">Published and draft</div></div></article>\n        </section>\n        <section class=\"ai-dashboard-grid\" aria-label=\"Available export files\">\n          <button type=\"button\" class=\"ai-dashboard-card\" data-report-export=\"training-directory\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-cap\"/></svg></span><h2>Training Directory CSV</h2></span><p>Download the current training topic directory.</p><span class=\"ai-dashboard-card-foot\"><span>Download CSV</span><svg class=\"icon\"><use href=\"#i-download\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-report-export=\"employee-history\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-users\"/></svg></span><h2>Employee History CSV</h2></span><p>Download the sample employee training history.</p><span class=\"ai-dashboard-card-foot\"><span>Download CSV</span><svg class=\"icon\"><use href=\"#i-download\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-report-export=\"case-reports\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-briefcase\"/></svg></span><h2>Case Reports CSV</h2></span><p>Export the current employee reporting register.</p><span class=\"ai-dashboard-card-foot\"><span>Download CSV</span><svg class=\"icon\"><use href=\"#i-download\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-report-export=\"audit-inspection\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></span><h2>Audit &amp; Inspection JSON</h2></span><p>Download both safety registers as standard JSON.</p><span class=\"ai-dashboard-card-foot\"><span>Download JSON</span><svg class=\"icon\"><use href=\"#i-download\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-report-export=\"published-content\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-message\"/></svg></span><h2>Published Content JSON</h2></span><p>Download released communications and library items.</p><span class=\"ai-dashboard-card-foot\"><span>Download JSON</span><svg class=\"icon\"><use href=\"#i-download\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-report-export=\"all-demo-data\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-download\"/></svg></span><h2>Full Demo Snapshot</h2></span><p>Download a JSON snapshot of the demo registers.</p><span class=\"ai-dashboard-card-foot\"><span>Download JSON</span><svg class=\"icon\"><use href=\"#i-download\"/></svg></span></button>\n        </section>\n        <div class=\"ua-security-note\" id=\"exportReportStatus\" aria-live=\"polite\">Exports are generated locally and do not include user passwords.</div>\n      </main>\n\n      <main class=\"page hidden\" id=\"directEntryPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-edit\"/></svg></div><div><h1>Direct Data Entry</h1><p class=\"page-subtitle\">Quick links to the workspace forms that capture safety data</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-edit\"/></svg><div><strong>Quick Entry Hub</strong><small>Choose a form below. Records continue to be managed in their existing demo modules.</small></div><span class=\"case-demo-badge\">Demo workflow</span></div>\n        <section class=\"ai-dashboard-grid\" aria-label=\"Direct data entry form links\">\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-scroll=\"single-entry\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-cap\"/></svg></span><h2>Training Entry</h2></span><p>Record a training session and employee attendance.</p><span class=\"ai-dashboard-card-foot\"><span>Open training form</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-scroll=\"bulk-entry\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-file\"/></svg></span><h2>Bulk Training Entry</h2></span><p>Add multiple employee training records from the spreadsheet-style grid.</p><span class=\"ai-dashboard-card-foot\"><span>Open bulk entry</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-nav=\"Case Management\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-briefcase\"/></svg></span><h2>Employee Safety Report</h2></span><p>Open the employee report register to review or add safety reports.</p><span class=\"ai-dashboard-card-foot\"><span>Open report register</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-ai=\"audit\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg></span><h2>Audit Form</h2></span><p>Start a PPE, tools, lifting, housekeeping or store audit.</p><span class=\"ai-dashboard-card-foot\"><span>Open audit form</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-ai=\"inspection\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-shield-alert\"/></svg></span><h2>Inspection Form</h2></span><p>Start a Vehicle Inspection or Fire Extinguisher checklist.</p><span class=\"ai-dashboard-card-foot\"><span>Open inspection form</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n          <button type=\"button\" class=\"ai-dashboard-card\" data-jump-nav=\"Daily Management\"><span class=\"ai-dashboard-card-head\"><span class=\"ai-dashboard-icon\"><svg class=\"icon\"><use href=\"#i-calendar\"/></svg></span><h2>Daily Management Log</h2></span><p>Capture a daily safety huddle and follow-up action.</p><span class=\"ai-dashboard-card-foot\"><span>Open daily log</span><svg class=\"icon\"><use href=\"#i-chevron-right\"/></svg></span></button>\n        </section>\n      </main>\n\n      <main class=\"page hidden\" id=\"dailyManagementPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-calendar\"/></svg></div><div><h1>Daily Management (DM)</h1><p class=\"page-subtitle\">Capture daily safety huddles, priorities and follow-up actions</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-calendar\"/></svg><div><strong>Daily HSE Huddle</strong><small>Demo log for shift safety focus and action tracking.</small></div><span class=\"case-demo-badge\">Demo records</span></div>\n        <section class=\"ai-summary-grid\" aria-label=\"Daily management summary\"><article class=\"stat-card\"><div class=\"stat-icon stat-blue\"><svg class=\"icon\"><use href=\"#i-calendar\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Daily Logs</div><div class=\"stat-value\" id=\"dmLogCount\">0</div><div class=\"stat-period\">All demo entries</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-orange\"><svg class=\"icon\"><use href=\"#i-clock\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Open Actions</div><div class=\"stat-value\" id=\"dmOpenActions\">0</div><div class=\"stat-period\">Awaiting follow-up</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-green\"><svg class=\"icon\"><use href=\"#i-checkcircle\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Closed Actions</div><div class=\"stat-value\" id=\"dmClosedActions\">0</div><div class=\"stat-period\">Completed in the demo</div></div></article><article class=\"stat-card\"><div class=\"stat-icon stat-purple\"><svg class=\"icon\"><use href=\"#i-users\"/></svg></div><div class=\"stat-copy\"><div class=\"stat-label\">Sites Covered</div><div class=\"stat-value\" id=\"dmSiteCount\">0</div><div class=\"stat-period\">Locations in the log</div></div></article></section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">NEW DAILY LOG</span><h2>Shift Safety Focus</h2><p>Record the main focus and one accountable follow-up action.</p></div></div><form id=\"dailyLogForm\" novalidate><div class=\"ai-form-grid\"><div class=\"ai-field\"><label for=\"dailyLogDate\">Date</label><input id=\"dailyLogDate\" type=\"date\"/></div><div class=\"ai-field\"><label for=\"dailyLogSite\">Site</label><select id=\"dailyLogSite\"><option>West Bokaro</option><option>Scrap Yard</option><option>Transport Park</option><option>Bog Area</option><option>Workshop</option></select></div><div class=\"ai-field\"><label for=\"dailyLogShift\">Shift</label><select id=\"dailyLogShift\"><option>Day</option><option>Night</option><option>General</option></select></div><div class=\"ai-field\"><label for=\"dailyLogLead\">Huddle lead</label><input id=\"dailyLogLead\" maxlength=\"80\" placeholder=\"Name of shift lead\"/></div><div class=\"ai-field full\"><label for=\"dailyLogFocus\">Today's safety focus</label><input id=\"dailyLogFocus\" maxlength=\"140\" placeholder=\"e.g. Vehicle-pedestrian separation at shift change\"/></div><div class=\"ai-field span2\"><label for=\"dailyLogAction\">Follow-up action</label><textarea id=\"dailyLogAction\" placeholder=\"Action required and expected outcome\"></textarea></div><div class=\"ai-field\"><label for=\"dailyLogOwner\">Action owner</label><input id=\"dailyLogOwner\" maxlength=\"80\" placeholder=\"Responsible person\"/></div><div class=\"ai-field\"><label for=\"dailyLogStatus\">Action status</label><select id=\"dailyLogStatus\"><option>Open</option><option>In Progress</option><option>Closed</option></select></div></div><div class=\"ai-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"dailyLogReset\">Reset</button><button type=\"submit\" class=\"btn btn-primary\">Save Daily Log</button></div></form></section>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">DAILY LOG REGISTER</span><h2>Recent Huddles &amp; Actions</h2><p>Mark an action complete or remove a demo entry.</p></div><span class=\"case-report-count\" id=\"dmRecordCount\">0 logs</span></div><div class=\"ai-toolbar\"><label class=\"ai-search\"><svg class=\"icon\"><use href=\"#i-search\"/></svg><input id=\"dmSearch\" type=\"search\" placeholder=\"Search focus, site, lead or owner...\"/></label><select id=\"dmStatusFilter\" aria-label=\"Filter daily action status\"><option value=\"\">All statuses</option><option>Open</option><option>In Progress</option><option>Closed</option></select><span class=\"case-result-count\" id=\"dmFilteredCount\">0 shown</span></div><div class=\"table-wrap\"><table class=\"ai-table\"><thead><tr><th>Date</th><th>Site / Shift</th><th>Lead</th><th>Safety Focus / Action</th><th>Owner</th><th>Status</th><th>Actions</th></tr></thead><tbody id=\"dmLogTableBody\"></tbody></table><div class=\"ai-empty hidden\" id=\"dmLogEmpty\">No daily logs match these filters.</div></div></section>\n      </main>\n\n      <main class=\"page hidden\" id=\"systemSettingsPage\">\n        <section class=\"page-heading\"><div class=\"heading-left\"><div class=\"heading-icon\"><svg class=\"icon\"><use href=\"#i-settings\"/></svg></div><div><h1>System Settings</h1><p class=\"page-subtitle\">Configure demo workspace preferences</p></div></div></section>\n        <div class=\"ai-source-note\"><svg class=\"icon\"><use href=\"#i-settings\"/></svg><div><strong>Workspace Preferences</strong><small>Changes apply to this page session only and do not modify server or authentication settings.</small></div><span class=\"case-demo-badge\">Demo settings</span></div>\n        <section class=\"panel ai-panel\"><div class=\"ai-panel-head\"><div><span class=\"eyebrow\">GENERAL</span><h2>Workspace Defaults</h2><p>Set the location and display preferences for this demo.</p></div><span class=\"case-report-count\" id=\"settingsSavedAt\">Defaults loaded</span></div><form id=\"systemSettingsForm\" novalidate><div class=\"ai-form-grid\"><div class=\"ai-field\"><label for=\"settingDefaultSite\">Default site</label><select id=\"settingDefaultSite\"><option>West Bokaro</option><option>Scrap Yard</option><option>Transport Park</option><option>Bog Area</option><option>Workshop</option></select></div><div class=\"ai-field\"><label for=\"settingDateFormat\">Date display</label><select id=\"settingDateFormat\"><option>DD MMM YYYY</option><option>DD/MM/YYYY</option><option>YYYY-MM-DD</option></select></div><div class=\"ai-field\"><label for=\"settingLandingPage\">Workspace landing section</label><select id=\"settingLandingPage\"><option>Audit &amp; Inspection</option><option>Dashboard</option><option>Training Management</option><option>Case Management</option></select></div><div class=\"ai-field\"><label for=\"settingLanguage\">Display language</label><select id=\"settingLanguage\"><option>English</option><option>English (India)</option></select></div></div><div class=\"ai-form-grid\" style=\"margin-top:10px\"><div class=\"ai-field full\"><label>Notifications and display</label><label class=\"radio-wrap\"><span><input id=\"settingSystemAlerts\" type=\"checkbox\"/> In-app system alerts</span></label><label class=\"radio-wrap\"><span><input id=\"settingWeeklySummary\" type=\"checkbox\"/> Weekly safety summary reminder</span></label><label class=\"radio-wrap\"><span><input id=\"settingCompactTables\" type=\"checkbox\"/> Compact table rows</span></label></div></div><div class=\"ai-form-actions\"><button type=\"button\" class=\"btn btn-light\" id=\"settingsReset\">Restore defaults</button><button type=\"submit\" class=\"btn btn-primary\" id=\"settingsSave\">Save Settings</button></div></form></section>\n        <div class=\"ua-security-note\" aria-live=\"polite\">Demo settings are held in memory until the page is reloaded. User accounts, permissions and authentication are managed separately in User &amp; Access Management.</div>\n      </main>\n\n    </div>\n  </div>\n\n  <div class=\"modal-backdrop\" id=\"modalBackdrop\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modalTitle\"><div class=\"modal-card\" id=\"modalCard\"><div class=\"modal-head\"><strong id=\"modalTitle\">Add training material</strong><button type=\"button\" id=\"closeModal\" aria-label=\"Close\"><svg class=\"icon\"><use href=\"#i-plus\"/></svg></button></div><div class=\"modal-body\" id=\"modalBody\"></div><div class=\"modal-foot\" id=\"modalFoot\"></div></div></div>\n  <div class=\"logout-overlay hidden\" id=\"logoutOverlay\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"logoutTitle\"><div class=\"logout-card\"><div class=\"logout-card-icon\"><svg class=\"icon\"><use href=\"#i-logout\"/></svg></div><h2 id=\"logoutTitle\">You are signed out</h2><p>This is a demo sign-out state. When Supabase Auth is enabled, log out signs out the provider session instead.</p><button type=\"button\" class=\"btn btn-primary\" id=\"resumeDemo\">Continue demo</button></div></div>\n  <div class=\"toast\" id=\"toast\" role=\"status\"></div>";
